    private fun symbol(name: String, vararg paths: String): ImageVector {
        val builder = ImageVector.Builder(
            name = name,
            defaultWidth = 24.dp,
            defaultHeight = 24.dp,
            viewportWidth = 960f,
            viewportHeight = 960f,
        )
        builder.addGroup(translationY = 960f)
        paths.forEach { builder.addPath(pathData = addPathNodes(it), fill = SolidColor(Color.Black)) }
        builder.clearGroup()
        return builder.build()
    }
